def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    minimum_balance = min(v1, v2)

    return {
        "value": minimum_balance,
        "trace": {
            "v1": v1,
            "v2": v2,
            "minimum_balance": minimum_balance,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
